 346→#[cfg(test)]
 347→mod tests {
 348→    use super::*;
 349→    use crate::ui::MockUI;
 350→    use std::fs;
 351→    use tempfile::TempDir;
 352→
 353→    fn setup_project(config_content: &str) -> TempDir {
 354→        let temp = TempDir::new().unwrap();
 355→        let bivvy_dir = temp.path().join(".bivvy");
 356→        fs::create_dir_all(&bivvy_dir).unwrap();
 357→        fs::write(bivvy_dir.join("config.yml"), config_content).unwrap();
 358→        temp
 359→    }
 360→
 361→    #[test]
 362→    fn run_command_creation() {
 363→        let temp = TempDir::new().unwrap();
 364→        let args = RunArgs::default();
 365→        let cmd = RunCommand::new(temp.path(), args);
 366→
 367→        assert_eq!(cmd.project_root(), temp.path());
 368→    }
 369→
 370→    #[test]
 371→    fn run_command_args() {
 372→        let temp = TempDir::new().unwrap();
 373→        let args = RunArgs {
 374→            workflow: "custom".to_string(),
 375→            dry_run: true,
 376→            ..Default::default()
 377→        };
 378→
 379→        let cmd = RunCommand::new(temp.path(), args);
 380→
 381→        assert_eq!(cmd.args().workflow, "custom");
 382→        assert!(cmd.args().dry_run);
 383→    }
 384→
 385→    #[test]
 386→    fn build_options_default() {
 387→        let temp = TempDir::new().unwrap();
 388→        let args = RunArgs::default();
 389→        let cmd = RunCommand::new(temp.path(), args);
 390→
 391→        let options = cmd.build_options();
 392→
 393→        assert!(options.only.is_empty());
 394→        assert!(options.skip.is_empty());
 395→        assert!(!options.dry_run);
 396→    }
 397→
 398→    #[test]
 399→    fn build_options_with_skip() {
 400→        let temp = TempDir::new().unwrap();
 401→        let args = RunArgs {
 402→            skip: vec!["step1".to_string(), "step2".to_string()],
 403→            ..Default::default()
 404→        };
 405→
 406→        let cmd = RunCommand::new(temp.path(), args);
 407→        let options = cmd.build_options();
 408→
 409→        assert!(options.skip.contains("step1"));
 410→        assert!(options.skip.contains("step2"));
 411→    }
 412→
 413→    #[test]
 414→    fn build_options_skip_behavior() {
 415→        let temp = TempDir::new().unwrap();
 416→
 417→        // Default
 418→        let args = RunArgs::default();
 419→        let cmd = RunCommand::new(temp.path(), args);
 420→        assert_eq!(
 421→            cmd.build_options().skip_behavior,
 422→            SkipBehavior::SkipWithDependents
 423→        );
 424→
 425→        // Skip only
 426→        let args = RunArgs {
 427→            skip_behavior: "skip_only".to_string(),
 428→            ..Default::default()
 429→        };
 430→        let cmd = RunCommand::new(temp.path(), args);
 431→        assert_eq!(cmd.build_options().skip_behavior, SkipBehavior::SkipOnly);
 432→
 433→        // Run anyway
 434→        let args = RunArgs {
 435→            skip_behavior: "run_anyway".to_string(),
 436→            ..Default::default()
 437→        };
 438→        let cmd = RunCommand::new(temp.path(), args);
 439→        assert_eq!(cmd.build_options().skip_behavior, SkipBehavior::RunAnyway);
 440→    }
 441→
 442→    #[test]
 443→    fn execute_with_no_config_returns_error() {
 444→        let temp = TempDir::new().unwrap();
 445→        let args = RunArgs::default();
 446→        let cmd = RunCommand::new(temp.path(), args);
 447→        let mut ui = MockUI::new();
 448→
 449→        let result = cmd.execute(&mut ui).unwrap();
 450→
 451→        assert!(!result.success);
 452→        assert_eq!(result.exit_code, 2);
 453→    }
 454→
 455→    #[test]
 456→    fn execute_with_unknown_workflow() {
 457→        let config = r#"
 458→app_name: test
 459→steps:
 460→  hello:
 461→    command: echo hello
 462→workflows:
 463→  default:
 464→    steps: [hello]
 465→"#;
 466→        let temp = setup_project(config);
 467→        let args = RunArgs {
 468→            workflow: "nonexistent".to_string(),
 469→            ..Default::default()
 470→        };
 471→        let cmd = RunCommand::new(temp.path(), args);
 472→        let mut ui = MockUI::new();
 473→
 474→        let result = cmd.execute(&mut ui).unwrap();
 475→
 476→        assert!(!result.success);
 477→        assert_eq!(result.exit_code, 1);
