        // Should succeed using the "quick" workflow instead of "default"
        assert!(result.success);
    }

    #[test]
    fn execute_explicit_workflow_overrides_env_default() {
        let config = r#"
app_name: Test Project
settings:
  environments:
    ci:
      default_workflow: quick
steps:
  hello:
    command: echo hello
  fast:
    command: echo fast
workflows:
  default:
